import java.util.*;

/** Rectangular 0/1 matrix, four neighbors; preserves input; iterative traversal avoids call-stack overflow. */
public final class MaxIslandArea {
    public static int maxArea(int[][] grid) {
        Objects.requireNonNull(grid, "grid"); int rows = grid.length;
        if (rows == 0) return 0;
        int cols = Objects.requireNonNull(grid[0], "row").length;
        if ((long) rows * cols > Integer.MAX_VALUE) throw new IllegalArgumentException("area exceeds int");
        for (int[] row : grid) { Objects.requireNonNull(row, "row"); if (row.length != cols) throw new IllegalArgumentException("ragged");
            for (int x : row) if (x != 0 && x != 1) throw new IllegalArgumentException("binary grid required"); }
        boolean[][] seen = new boolean[rows][cols]; int best = 0;
        ArrayDeque<int[]> queue = new ArrayDeque<>(); int[] dr = {-1,1,0,0}, dc = {0,0,-1,1};
        for (int r = 0; r < rows; r++) for (int c = 0; c < cols; c++) {
            if (grid[r][c] == 0 || seen[r][c]) continue;
            seen[r][c] = true; queue.addLast(new int[]{r,c}); int area = 0;
            while (!queue.isEmpty()) {
                int[] cell = queue.removeFirst(); area++;
                for (int d = 0; d < 4; d++) { int nr = cell[0] + dr[d], nc = cell[1] + dc[d];
                    if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == 1 && !seen[nr][nc]) {
                        seen[nr][nc] = true; queue.addLast(new int[]{nr,nc});
                    }
                }
            }
            best = Math.max(best, area);
        }
        return best;
    }
    static int root(int[] parent, int x) { while (parent[x] != x) x = parent[x]; return x; }
    static int oracle(int[][] g) {
        int rows = g.length, cols = rows == 0 ? 0 : g[0].length; int[] p = new int[rows * cols], size = new int[p.length];
        for (int i = 0; i < p.length; i++) { p[i] = i; size[i] = 1; }
        for (int r = 0; r < rows; r++) for (int c = 0; c < cols; c++) if (g[r][c] == 1) {
            for (int[] next : new int[][]{{r + 1,c},{r,c + 1}}) if (next[0] < rows && next[1] < cols && g[next[0]][next[1]] == 1) {
                int x = root(p,r * cols + c), y = root(p,next[0] * cols + next[1]); if (x != y) { p[x] = y; size[y] += size[x]; }
            }
        }
        int best = 0; for (int r = 0; r < rows; r++) for (int c = 0; c < cols; c++) if (g[r][c] == 1) best = Math.max(best, size[root(p,r * cols + c)]);
        return best;
    }
    static void check(boolean b) { if (!b) throw new AssertionError(); }
    static void compare(int[][] g) { int[][] before = Arrays.stream(g).map(int[]::clone).toArray(int[][]::new); check(maxArea(g) == oracle(g)); check(Arrays.deepEquals(g,before)); }
    public static void main(String[] args) {
        for (int mask = 0; mask < 512; mask++) { int[][] g = new int[3][3]; for (int i = 0; i < 9; i++) g[i / 3][i % 3] = (mask >>> i) & 1; compare(g); }
        Random random = new Random(20261009);
        for (int i = 0; i < 2000; i++) { int[][] g = new int[random.nextInt(8)][random.nextInt(8)]; for (int[] row : g) for (int j = 0; j < row.length; j++) row[j] = random.nextBoolean() ? 1 : 0; compare(g); }
        check(maxArea(new int[][]{{1,0},{0,1}}) == 1); check(maxArea(new int[][]{{1,1,1,1}}) == 4);
        int[][] longRow = new int[1][100000]; Arrays.fill(longRow[0],1); check(maxArea(longRow) == 100000);
        for (int[][] bad : new int[][][]{{{1},{1,0}},{{2}}}) try { maxArea(bad); throw new AssertionError(); } catch (IllegalArgumentException expected) { }
        try { maxArea(new int[][]{null}); throw new AssertionError(); } catch (NullPointerException expected) { }
        try { maxArea(null); throw new AssertionError(); } catch (NullPointerException expected) { }
        System.out.println("PASS all512 binary3x3 +2000 random rectangles against DSU oracle;empty/diagonal/100000-cell no-recursion;input preserved;invalid rejection");
    }
}

import java.util.ArrayDeque;
import java.util.Objects;
public final class IslandCount {
    private IslandCount() { }
    // Rectangular binary int grid, four neighbors; never mutates input.
    public static int count(int[][] grid) {
        Objects.requireNonNull(grid);
        int rows = grid.length;
        if (rows == 0) return 0;
        int cols = Objects.requireNonNull(grid[0]).length;
        if ((long) rows * cols > Integer.MAX_VALUE) throw new IllegalArgumentException("grid too large");
        for (int[] row : grid) {
            Objects.requireNonNull(row);
            if (row.length != cols) throw new IllegalArgumentException("ragged grid");
            for (int value : row) if (value != 0 && value != 1) throw new IllegalArgumentException("binary grid required");
        }
        if (cols == 0) return 0;
        boolean[][] seen = new boolean[rows][cols];
        ArrayDeque<int[]> queue = new ArrayDeque<>();
        int[] dr = {-1, 1, 0, 0}, dc = {0, 0, -1, 1};
        int islands = 0;
        for (int r = 0; r < rows; r++) for (int c = 0; c < cols; c++) {
            if (grid[r][c] == 0 || seen[r][c]) continue;
            islands++;
            seen[r][c] = true;
            queue.addLast(new int[] {r, c});
            while (!queue.isEmpty()) {
                int[] cell = queue.removeFirst();
                for (int d = 0; d < 4; d++) {
                    int nr = cell[0] + dr[d], nc = cell[1] + dc[d];
                    if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == 1 && !seen[nr][nc]) {
                        seen[nr][nc] = true;
                        queue.addLast(new int[] {nr, nc});
                    }
                }
            }
        }
        return islands;
    }
}
